package com.orderflow.delivery.service;
import com.orderflow.delivery.domain.*;import com.orderflow.delivery.error.DeliveryDomainException;import com.orderflow.delivery.repository.*;import com.orderflow.platform.error.ErrorCode;import io.micrometer.core.instrument.MeterRegistry;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DeliveryCommandService{private static final Set<String>CODES=Set.of("CUSTOMER_UNAVAILABLE","ADDRESS_PROBLEM","PACKAGE_DAMAGED","VEHICLE_PROBLEM","OTHER");private final DeliveryRepository deliveries;private final DeliveryAgentRepository agents;private final DeliveryStatusHistoryRepository history;private final DeliveryEventOutbox events;private final MeterRegistry metrics;private final Clock clock;public DeliveryCommandService(DeliveryRepository d,DeliveryAgentRepository a,DeliveryStatusHistoryRepository h,DeliveryEventOutbox e,MeterRegistry m,Clock c){deliveries=d;agents=a;history=h;events=e;metrics=m;clock=c;}
 @Transactional public Delivery pickup(UUID user,UUID id,String c){return transition(user,id,c,DeliveryStatus.PICKED_UP,null);}@Transactional public Delivery outForDelivery(UUID user,UUID id,String c){return transition(user,id,c,DeliveryStatus.OUT_FOR_DELIVERY,null);}@Transactional public Delivery delivered(UUID user,UUID id,String c){return transition(user,id,c,DeliveryStatus.DELIVERED,null);}@Transactional public Delivery failed(UUID user,UUID id,String code,String c){if(!CODES.contains(code))throw error(HttpStatus.BAD_REQUEST,ErrorCode.DELIVERY_STATE_CONFLICT,"Failure code is invalid");return transition(user,id,c,DeliveryStatus.FAILED,code);}
 private Delivery transition(UUID user,UUID id,String correlation,DeliveryStatus next,String failure){Delivery d=deliveries.lockById(id).orElseThrow(()->error(HttpStatus.NOT_FOUND,ErrorCode.DELIVERY_NOT_FOUND,"Delivery not found"));DeliveryAgentProfile a=agents.lockByUserId(user).orElseThrow(()->error(HttpStatus.NOT_FOUND,ErrorCode.DELIVERY_NOT_FOUND,"Delivery not found"));if(!a.getId().equals(d.getDeliveryAgentId()))throw error(HttpStatus.NOT_FOUND,ErrorCode.DELIVERY_NOT_FOUND,"Delivery not found");if(d.getStatus()==next)return d;DeliveryStatus previous=d.getStatus();Instant now=Instant.now(clock);try{switch(next){case PICKED_UP->d.pickup(now);case OUT_FOR_DELIVERY->d.outForDelivery(now);case DELIVERED->d.delivered(now);case FAILED->d.failed(failure,now);default->throw new IllegalArgumentException();}}catch(IllegalStateException e){throw error(HttpStatus.CONFLICT,ErrorCode.DELIVERY_STATE_CONFLICT,"Delivery state transition is not allowed");}history.save(new DeliveryStatusHistory(id,previous,next,user,null,correlation,now));switch(next){case PICKED_UP->{events.pickedUp(d,correlation,now);metrics.counter("deliveries_picked_up_total").increment();}case OUT_FOR_DELIVERY->{events.outForDelivery(d,correlation,now);metrics.counter("deliveries_out_for_delivery_total").increment();}case DELIVERED->{events.delivered(d,correlation,now);a.released(now);metrics.counter("deliveries_completed_total").increment();}case FAILED->{events.failed(d,failure,correlation,now);a.released(now);metrics.counter("deliveries_failed_total","failureCategory",failure).increment();}default->{}}return d;}
 private DeliveryDomainException error(HttpStatus s,ErrorCode c,String m){return new DeliveryDomainException(s,c,m);}
}
